const now = new Date();
const dateParts = value => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(value);
const localDate = value => {
  const parts = dateParts(value);
  const get = type => parts.find(part => part.type === type).value;
  return `${get('year')}-${get('month')}-${get('day')}`;
};
const today = localDate(now);
const offset = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Tehran', timeZoneName: 'longOffset' }).formatToParts(now).find(part => part.type === 'timeZoneName').value.replace('GMT', '');
const todayStart = new Date(`${today}T00:00:00${offset}`);
const since = new Date(todayStart.getTime() - 86400000);
return [{ json: { reportDate: localDate(since), since: since.toISOString(), until: todayStart.toISOString(), generatedAt: now.toISOString() } }];

const window = $('Yesterday window').first().json;
const command = $input.first().json;
let archive = { remainingTodos: [], archivedDaily: 0, archivedBriefings: 0 };
try {
  archive = { ...archive, ...JSON.parse(command.stdout || '{}') };
} catch (error) {
  throw new Error(`Archive command returned invalid JSON: ${error.message}`);
}
return [{ json: { ...window, archive } }];

const prior = $('Collect archive result').first().json;
const command = $input.first().json;
let calendar = { meetings: [], calendarConfigured: false };
try {
  calendar = { ...calendar, ...JSON.parse(command.stdout || '{}') };
} catch (error) {
  throw new Error(`Calendar command returned invalid JSON: ${error.message}`);
}
return [{ json: { ...prior, calendar } }];

const window = $('Yesterday window').first().json;
const rows = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
return [{ json: { ...window, commits: rows.filter(row => row && row.id) } }];

const prior = $('Collect commits').first().json;
const rows = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
return [{ json: { ...prior, mergeRequests: rows.filter(row => row && row.id) } }];

const prior = $('Collect merge requests').first().json;
const rows = $input.all().flatMap(item => Array.isArray(item.json) ? item.json : [item.json]);
return [{ json: { ...prior, pipelines: rows.filter(row => row && row.id) } }];

const payloads = $input.all().map(item => item.json);
const projects = payloads.flatMap(value => Array.isArray(value) ? value : (value.results || []));
return projects.map(project => ({ json: { projectId: project.id, projectName: project.name, projectIdentifier: project.identifier } }));

const asArray = value => Array.isArray(value) ? value : (Array.isArray(value?.results) ? value.results : (value?.id ? [value] : []));
const reportDate = String($('Collect pipelines').first().json.reportDate || '').slice(0, 10);
const cycles = asArray($json.cyclesResponse).filter(cycle => !cycle.deleted_at && !cycle.archived_at);
const activeStatuses = new Set(['current', 'active', 'started', 'in-progress', 'in_progress']);
const hasActiveStatus = cycle => cycle.is_current === true || activeStatuses.has(String(cycle.status || cycle.cycle_view || cycle.state || '').toLowerCase());
const containsReportDate = cycle => {
  const start = String(cycle.start_date || '').slice(0, 10);
  const end = String(cycle.end_date || '').slice(0, 10);
  return Boolean(reportDate && start && end && start <= reportDate && reportDate <= end);
};
const activeCycle = cycles.find(hasActiveStatus) || cycles.find(containsReportDate) || (cycles.length === 1 ? cycles[0] : null);
const cycleSelection = {
  reportDate,
  cyclesFound: cycles.length,
  cycleNames: cycles.map(cycle => cycle.name),
  selectedCycleId: activeCycle?.id || null,
  selectedCycleName: activeCycle?.name || null
};
return { json: { ...$json, cyclesFound: cycles.length, cycleSelection, activeCycle } };

const gitlab = $('Collect pipelines').first().json;
const archive = $('Collect archive result').first().json.archive;
const remainingTodos = Array.isArray(archive.remainingTodos) ? archive.remainingTodos : [];
const calendar = $('Collect calendar result').first().json.calendar;
const meetings = Array.isArray(calendar.meetings) ? calendar.meetings : [];
const rows = $input.all().map(item => item.json);
const asArray = value => Array.isArray(value) ? value : (value?.results || []);
const privateConfig = {
  reportTitle: $env.WORK_REPORT_TITLE || 'Work',
  planeBaseUrl: String($env.PLANE_BASE_URL || '').replace(/\/$/, ''),
  planeWorkspaceSlug: String($env.PLANE_WORKSPACE_SLUG || ''),
  gitlabProjectWebUrl: String($env.GITLAB_PROJECT_WEB_URL || '')
};
const now = new Date(gitlab.until);
const windowStart = new Date(gitlab.since);
const inWindow = value => value && new Date(value) >= windowStart && new Date(value) < now;
const esc = value => String(value ?? '').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const link = (label, url) => url ? `[${esc(label)}](${url})` : esc(label);
const itemLine = item => `- ${link(`${item.project}: ${item.name}`, item.url)} — **${esc(item.state)}**${item.owner ? ` — ${esc(item.owner)}` : ''}${item.targetDate ? ` — due ${item.targetDate}` : ''}`;
const cycleWorkItemId = relation => {
  const related = relation?.issue?.id ?? relation?.issue_id ?? relation?.issue ?? relation?.work_item?.id ?? relation?.work_item_id ?? relation?.work_item;
  if (related !== undefined && related !== null && typeof related !== 'object') return String(related);
  // Some Plane releases return expanded work items directly instead of a
  // cycle-to-item relation. Only then is the row's own id the work-item id.
  if (relation?.id && (relation.name || relation.sequence_id)) return String(relation.id);
  return null;
};
const projects = rows.map(row => {
  const states = asArray(row.statesResponse);
  const stateMap = new Map(states.map(state => [String(state.id), state]));
  const cycleRows = asArray(row.cycleItemsResponse);
  const currentCycleItemIds = new Set(cycleRows.map(cycleWorkItemId).filter(Boolean));
  return { ...row.project, activeCycle: row.activeCycle || null, cycleRowCount: cycleRows.length, currentCycleItemIds, stateMap, workItems: asArray(row.workItemsResponse), pages: asArray(row.pagesResponse), pagesError: row.pagesResponse?.error || row.pagesResponse?.message || null };
});
const workItems = projects.flatMap(project => project.workItems.map(item => {
  const stateId = String(item.state?.id || item.state || '');
  const state = item.state_detail || (typeof item.state === 'object' ? item.state : null) || project.stateMap.get(stateId) || {};
  const group = String(state.group || state.state_group || '').toLowerCase();
  return {
    id: String(item.id),
    project: project.projectName || project.projectIdentifier,
    name: item.name || 'Untitled',
    state: state.name || stateId || 'Unknown',
    group,
    priority: String(item.priority || 'none').toLowerCase(),
    owner: asArray(item.assignees).map(person => person.display_name || person.name || person.email || person).join(', '),
    targetDate: item.target_date || null,
    updatedAt: item.updated_at || null,
    completedAt: item.completed_at || null,
    cancelledAt: item.cancelled_at || null,
    inCurrentCycle: Boolean(project.activeCycle && project.currentCycleItemIds.has(String(item.id))),
    url: `${privateConfig.planeBaseUrl}/${privateConfig.planeWorkspaceSlug}/projects/${project.projectId}/issues/${item.id}`
  };
}));
const open = workItems.filter(item => !item.completedAt && !item.cancelledAt && !['completed', 'cancelled', 'canceled'].includes(item.group));
const current = open.filter(item => item.inCurrentCycle);
const cycleRowsFound = projects.reduce((total, project) => total + project.cycleRowCount, 0);
const cycleIdsResolved = projects.reduce((total, project) => total + project.currentCycleItemIds.size, 0);
const currentInProgress = current.filter(item => item.group === 'started');
const currentTodo = current.filter(item => item.group !== 'started');
const overdue = open.filter(item => item.targetDate && new Date(`${item.targetDate}T23:59:59Z`) < now);
const upcoming = open.filter(item => item.targetDate && new Date(`${item.targetDate}T23:59:59Z`) >= now && new Date(`${item.targetDate}T23:59:59Z`) <= new Date(now.getTime() + 7 * 86400000));
const recentlyChanged = workItems.filter(item => inWindow(item.updatedAt) || inWindow(item.completedAt));
const failedPipelines = gitlab.pipelines.filter(pipeline => ['failed', 'canceled'].includes(pipeline.status));
const openMrs = gitlab.mergeRequests.filter(mr => mr.state === 'opened');
const recentPages = projects.flatMap(project => project.pages.map(page => ({ project: project.projectName || project.projectIdentifier, name: page.name || 'Untitled', updatedAt: page.updated_at, url: `${privateConfig.planeBaseUrl}/${privateConfig.planeWorkspaceSlug}/projects/${project.projectId}/pages/${page.id}` }))).filter(page => page.updatedAt).sort((a, b) => String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0, 10);
const pagesUnavailable = projects.some(project => project.pagesError);
const section = (title, values, render, empty = '- Nothing found.') => [`## ${title}`, '', ...(values.length ? values.map(render) : [empty]), ''];
const lines = [
  '---',
  'type: briefing',
  `date: ${gitlab.reportDate}`,
  `generated_at: ${gitlab.generatedAt}`,
  'generated_by: n8n',
  'sources:',
  '  - plane',
  '  - gitlab',
  '---',
  '',
  `# ${privateConfig.reportTitle} brief — ${gitlab.reportDate}`,
  '',
  '> [!info]',
  '> Generated deterministically from Plane and GitLab. Personal notes and meeting context remain elsewhere in this vault.',
  '',
  '## Remaining todos from previous daily notes',
  '',
  ...(remainingTodos.length ? remainingTodos.map(todo => `- [ ] ${esc(todo.text)} — [[${String(todo.path).replace(/\.md$/, '')}|${todo.date}]]`) : ['- No unfinished todos found in previous daily notes.']),
  '',
  '## Meetings requiring documentation — past 30 days',
  '',
  ...(meetings.length ? meetings.map(meeting => `- ${String(meeting.start).slice(0, 10)} ${String(meeting.start).slice(11, 16)} — [[${String(meeting.path).replace(/\.md$/, '')}|${esc(meeting.title)}]] — missing: ${meeting.missingSections.map(esc).join(', ')}`) : [calendar.calendarConfigured ? '- All non-routine meetings in the past 30 days are documented.' : '- Calendar feed is not configured.']),
  '',
  '## At a glance',
  '',
  `- ${gitlab.commits.length} GitLab commit(s)`,
  `- ${openMrs.length} open merge request(s) touched since yesterday`,
  `- ${failedPipelines.length} failed or canceled pipeline(s)`,
  `- ${recentlyChanged.length} Plane work item(s) changed`,
  `- ${current.length} open current-cycle item(s) across ${projects.filter(project => project.activeCycle).length} project(s)`,
  ...(cycleRowsFound > 0 && current.length === 0 ? [`- ⚠️ Plane returned ${cycleRowsFound} cycle membership row(s); ${cycleIdsResolved} item ID(s) were resolved but none matched an open project work item.`] : []),
  '',
  ...section('Deadlines', [...overdue, ...upcoming], itemLine, '- No overdue or next-seven-day deadlines found.'),
  ...section('Current cycle — in progress', currentInProgress, itemLine),
  ...section('Current cycle — todo', currentTodo, itemLine),
  ...section('Plane changes yesterday', recentlyChanged, itemLine),
  ...section('GitLab commits', gitlab.commits, commit => `- ${link(commit.title, commit.web_url)} — ${esc(commit.author_name)}${commit.short_id ? ` (\`${commit.short_id}\`)` : ''}`),
  ...section('Open merge requests touched yesterday', openMrs, mr => `- ${link(`!${mr.iid} ${mr.title}`, mr.web_url)} — ${esc(mr.author?.name || '')}`),
  ...section('Pipelines needing attention', failedPipelines, pipeline => `- ${link(`#${pipeline.id} ${pipeline.ref || ''}`, pipeline.web_url)} — **${esc(pipeline.status)}**`),
  ...section('Recently updated Plane pages', recentPages, page => `- ${link(`${page.project}: ${page.name}`, page.url)} — ${String(page.updatedAt).slice(0, 10)}`, pagesUnavailable ? '- Unavailable: this self-hosted Plane release does not expose Pages to API-key clients.' : '- No recently updated pages found.'),
  '## Source systems',
  '',
  `- [Plane](${privateConfig.planeBaseUrl}/)`,
  `- [GitLab](${privateConfig.gitlabProjectWebUrl})`,
  ''
];
const markdown = lines.join('\n');
const fileName = `${gitlab.reportDate}.md`;
return [{ json: { reportDate: gitlab.reportDate, fileName, targetPath: `/var/lib/obsidian-vault/Briefings/${fileName}`, markdown }, binary: { data: { data: Buffer.from(markdown, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName, fileExtension: 'md' } } }];
